// Date du jour en DD/MM/YYYY (fuseau Europe/Paris)
const todayStr = new Date().toLocaleDateString('fr-FR', {
  timeZone: 'Europe/Paris',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric'
});

// Garder uniquement les articles prévus aujourd'hui avec statut 'À publier'
return items.filter(item => {
  const date = (item.json['Date'] || '').trim();
  const statut = (item.json['Statut'] || '').trim();
  return date === todayStr && statut === 'À publier';
});

// Récupérer les données de la ligne du sheet
const sheetData = $('Filtrer articles du jour').item.json;

// Récupérer le contenu généré par Claude (réponse HTTP brute)
const content = $input.item.json.content[0].text || '';

if (!content) throw new Error('Contenu Claude vide — vérifiez la réponse de l\'API Anthropic');

const titre = sheetData['Titre'] || '';
const categorie = sheetData['Catégorie'] || '';
const imageUrl = sheetData['Image URL'] || '';
const date = sheetData['Date'] || '';
const rowNumber = sheetData['row_number'] || '';

// Convertir DD/MM/YYYY → YYYY-MM-DD
const parts = date.split('/');
const isoDate = parts.length === 3 ? `${parts[2]}-${parts[1]}-${parts[0]}` : date;

// Générer slug URL
const slug = titre
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/['']/g, '')
  .replace(/[^a-z0-9\s-]/g, '')
  .trim()
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-');

// Générer meta description (160 chars max)
const cleanContent = content
  .replace(/^#{1,6}\s.+$/gm, '')
  .replace(/\*\*([^*]+)\*\*/g, '$1')
  .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
  .replace(/\n+/g, ' ')
  .trim();
const description = (cleanContent.length > 157
  ? cleanContent.substring(0, 157) + '...'
  : cleanContent
).replace(/"/g, "'");

// Construire le MDX complet
const titreEscaped = titre.replace(/"/g, "'");
const mdx = `---
title: "${titreEscaped}"
description: "${description}"
pubDate: ${isoDate}
image: "${imageUrl}"
imageAlt: "${titreEscaped}"
category: "${categorie}"
---

${content}`;

// Encoder en base64 pour l'API GitHub
const mdxBase64 = Buffer.from(mdx, 'utf-8').toString('base64');

return [{ json: { slug, mdxBase64, titre, date, isoDate, rowNumber, categorie, imageUrl } }];
